export const ZONE='Asia/Ho_Chi_Minh',DAY=86400000;
export function calendarDate(now=Date.now()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(now)).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;}
export function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const date=new Date(value+'T00:00:00Z');return Number.isFinite(+date)&&date.toISOString().slice(0,10)===value&&value>='1900-01-01'&&value<='2200-12-31';}
export function deadline(exam){return exam.time?Date.parse(exam.date+'T'+exam.time+':00+07:00'):Date.parse(exam.date+'T00:00:00+07:00')+DAY-1;}
export function daysLeft(exam,now=Date.now()){return Math.round((Date.parse(exam.date+'T00:00:00Z')-Date.parse(calendarDate(now)+'T00:00:00Z'))/DAY);}
export function examState(exam,now=Date.now()){const days=daysLeft(exam,now),passed=deadline(exam)<now,added=Date.parse(calendarDate(Date.parse(exam.addedAt))+'T00:00:00Z'),duration=(Date.parse(exam.date+'T00:00:00Z')-added)/DAY,elapsed=(Date.parse(calendarDate(now)+'T00:00:00Z')-added)/DAY;return {days,passed,label:passed?'Passed':days===0?'Today · good luck':days===1?'Tomorrow':days+' days',urgency:days>30?'calm':days>7?'upcoming':'soon',urgencyLabel:days>30?'Plenty of time':days>7?'Coming up':'Due soon',progress:duration<=0?100:Math.round(Math.max(0,Math.min(1,elapsed/duration))*100),weeks:Math.max(0,days)/7};}
export function tickLabel(exam,now=Date.now()){const seconds=Math.max(0,Math.ceil((deadline(exam)-now)/1000));return [Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(n=>String(n).padStart(2,'0')).join(':');}
export function validateExam(input){const text=(x,n)=>typeof x==='string'?x.trim().slice(0,n):'';if(!input||typeof input!=='object')throw Error('Choose a valid exam.');const exam={id:text(input.id,100),subject:text(input.subject,150),courseId:text(input.courseId,250),type:input.type,date:input.date,time:input.time||'',location:text(input.location,200),note:text(input.note,2000),addedAt:input.addedAt};if(!/^[\w-]{1,100}$/.test(exam.id)||!exam.subject)throw Error('Choose a subject or enter its name.');if(!['Midterm','Final','Quiz','Other'].includes(exam.type))throw Error('Choose an exam type.');if(!validDate(exam.date))throw Error('Choose a valid exam date.');if(exam.time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(exam.time))throw Error('Choose a valid time.');if(!Number.isFinite(Date.parse(exam.addedAt)))throw Error('The exam creation date is invalid.');return exam;}
export function orderedExams(exams,now=Date.now()){const sorted=[...exams].sort((a,b)=>deadline(a)-deadline(b)||a.subject.localeCompare(b.subject));return {upcoming:sorted.filter(e=>!examState(e,now).passed),completed:sorted.filter(e=>examState(e,now).passed).reverse()};}
export const duplicateExam=(exams,exam)=>exams.some(e=>e.id!==exam.id&&e.subject.toLowerCase()===exam.subject.toLowerCase()&&e.type===exam.type&&e.date===exam.date&&e.time===exam.time);
